@Injectable()
export class OrderService {
  constructor(private readonly prisma: PrismaService, private readonly stock: StockGateway) {}

  place(req: OrderRequest): Promise<Order> {
    return this.prisma.$transaction(async (tx) => {   // throw => rollback
      const order = await tx.order.create({ data: toRow(req) });
      await this.stock.reserve(tx, order.id);          // same tx client
      return order;
    });
  }
}
